// Register key bindings
public class MyMod {
    public static KeyMapping KEY_MY_ACTION;

    public MyMod() {
        // Register key mapping in client setup
        FMLJavaModLoadingContext.get().getModEventBus().addListener(this::registerKeys);
    }

    private void registerKeys(RegisterKeyMappingsEvent event) {
        KEY_MY_ACTION = new KeyMapping(
            "key.my_mod.action", // Translation key
            KeyConflictContext.IN_GAME, // Conflict context
            InputMappings.Type.KEYSYM, // Type
            GLFW.GLFW_KEY_K, // Key code
            "key.categories.mod" // Category
        );
        event.register(KEY_MY_ACTION);
    }
}

// Listen for key press
@Mod.EventBusSubscriber(modid = MODID, bus = Mod.EventBusSubscriber.Bus.FORGE, value = Dist.CLIENT)
public class KeyInputHandler {
    @SubscribeEvent
    public static void onKeyInput(InputEvent.Key event.getKey()) {
        if (MyMod.KEY_MY_ACTION.isDown()) {
            // Key was pressed
        }
    }
}
